'use strict';
const LIBRARY = window.SIA_LIBRARY || [];
const LEVELS = [
 {name:'작은 새싹',file:'calm.png',note:'세상을 처음 만나는 하루',age:'유치원 5세'},
 {name:'반짝이는 호기심',file:'happy.png',note:'새로운 낱말이 궁금한 하루',age:'유치원 6세'},
 {name:'이야기 발견가',file:'curious.png',note:'이야기 속 질문을 찾는 하루',age:'초등 1학년'},
 {name:'호기심 탐험가',file:'inspect.png',note:'왜 그럴까? 함께 살펴보는 하루',age:'초등 2학년'},
 {name:'생각 수집가',file:'searching.png',note:'자세히 보고 생각을 모으는 하루',age:'초등 3–4학년'},
 {name:'아이디어 발명가',file:'new-insight.png',note:'나만의 답을 만들어 가는 하루',age:'초등 5학년'},
 {name:'반짝이는 개척자',file:'summer.png',note:'더 넓은 세상으로 나아가는 하루',age:'초등 6학년'}
];
const ICONS={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 5v16M3 3h5c2 0 4 2 4 2s2-2 4-2h5v16h-5c-2 0-4 2-4 2s-2-2-4-2H3Z',pencil:'m15 4 5 5M4 16 16 4a2 2 0 0 1 3 3L7 19l-4 1Z',spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7ZM19 3v4m-2-2h4',chart:'M4 20V10m8 10V4m8 16v-7',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',check:'m5 12 4 4L19 6',leaf:'M20 3C9 2 3 7 4 14s12 9 16-11ZM4 21 16 8',close:'m6 6 12 12M6 18 18 6',settings:'M9 3h6l1 4 4 1v8l-4 1-1 4H9l-1-4-4-1V8l4-1ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',cloud:'M6 18h12a4 4 0 0 0 0-8 6 6 0 0 0-12-1 4.5 4.5 0 0 0 0 9',heart:'M12 21 3 12C-2 4 8 0 12 7c4-7 14-3 9 5Z',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',back:'M20 12H4m6-6-6 6 6 6',volume:'M11 4 5 9H2v6h3l6 5ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',undo:'M3 10h11a6 6 0 0 1 0 12M3 10l5-5M3 10l5 5',erase:'m3 14 9-10 9 8-9 10H9ZM7 10l9 8M12 22h10',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',lock:'M6 11h12v10H6ZM8 11V7a4 4 0 0 1 8 0v4'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${ICONS[n]||ICONS.spark}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('sv-SE');
const DEFAULT={name:'',age:null,gender:null,interests:[],readingPreferences:{},profileVersion:0,onboardingCompleted:false,ko:3,en:3,daily:2,lang:'ko',completed:{},checkins:{},lastItem:null};
let state;try{state={...DEFAULT,...JSON.parse(localStorage.getItem('my-sia-v1')||'{}')};}catch{state={...DEFAULT};}
let route='home',filter={lang:'all',kind:'all',query:'',topic:''};
const PROFILE=window.SiaProfile;
if(PROFILE.complete(state)){state.ko=state.en=PROFILE.ageStage(state.age);}
let parentUnlockedUntil=0;
const isParent=()=>Date.now()<parentUnlockedUntil;
const hasLibrary=()=>window.SiaLearning.core.libraryItems(LIBRARY,state).length>0;
function parentGate(){shell();document.querySelector('#main').innerHTML='<section class="learning-parent-card parent-gate"><h1>부모님이 열어 주세요</h1><p>엄마·아빠(보호자) <strong>본인의 출생연도</strong>를 입력해 주세요.</p><p class="parent-gate-note">설정된 비밀번호는 없어요. 보호자가 직접 여는지 확인하는 단계이며, 입력한 연도는 저장하지 않아요.</p><form id="parent-gate-form"><label>부모님 출생연도 · 네 자리<input name="year" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="off" required aria-label="부모님 출생연도" placeholder="네 자리 연도"></label><button class="btn primary">부모님 공간 열기</button><p role="status" id="parent-gate-error"></p></form><a href="#home" class="btn outline">돌아가기</a></section>';}
document.addEventListener('submit',e=>{if(e.target.id!=='parent-gate-form')return;e.preventDefault();const raw=String(new FormData(e.target).get('year')),y=Number(raw);if(!/^[0-9]{4}$/.test(raw)||y<1930||y>new Date().getFullYear()-18){document.querySelector('#parent-gate-error').textContent='아이의 출생연도 대신, 부모님(성인) 본인의 출생연도를 네 자리로 입력해 주세요.';return;}parentUnlockedUntil=Date.now()+10*60*1000;render();});
let onboarding=null;
const SETUP_STEPS=[{key:'name',question:'이름이 뭐야?'},{key:'age',question:'몇 살이야?'},{key:'gender',question:'여자아이야, 남자아이야?'},{key:'interests',question:'무엇을 좋아해?'},{key:'ko',question:'한글은 어떻게 읽어?'},{key:'en',question:'영어는 어때?'},{key:'storyLevel',question:'나에게 맞춰 시작해 볼까?'}];
function profileReady(){return PROFILE.complete(state);}
function newDraft(){return {storyLevel:1,name:state.name||'',age:state.age??null,gender:state.gender??null,interests:[...(state.interests||[])],readingPreferences:{ko:state.readingPreferences?.ko||null,en:state.readingPreferences?.en||null}};}
function setupSession(){if(onboarding)return onboarding;let saved;try{saved=JSON.parse(localStorage.getItem('my-sia-intro-draft')||'null');}catch{}const draft=newDraft();if(saved?.draft){const d=saved.draft;draft.name=typeof d.name==='string'?d.name.slice(0,12):draft.name;draft.age=Number.isInteger(d.age)&&d.age>=5&&d.age<=13?d.age:null;draft.storyLevel=1;draft.gender=['girl','boy','skip'].includes(d.gender)?d.gender:null;draft.interests=Array.isArray(d.interests)?[...new Set(d.interests)].filter(id=>PROFILE.interests.some(t=>t.id===id)).slice(0,3):[];for(const lang of ['ko','en'])draft.readingPreferences[lang]=PROFILE.choices[lang].some(c=>c.id===d.readingPreferences?.[lang])?d.readingPreferences[lang]:null;}onboarding={step:Math.min(SETUP_STEPS.length-1,Math.max(0,Number.isInteger(saved?.step)?saved.step:0)),draft,editing:false};return onboarding;}
function persistDraft(){try{localStorage.setItem('my-sia-intro-draft',JSON.stringify(onboarding));}catch{}}
function stepReady(){const {step,draft}=setupSession(),key=SETUP_STEPS[step].key;if(key==='storyLevel')return Number.isInteger(draft.storyLevel)&&draft.storyLevel>=1&&draft.storyLevel<=5;if(key==='name')return Boolean(draft.name.trim());if(key==='age')return Number.isInteger(draft.age);if(key==='gender')return ['girl','boy','skip'].includes(draft.gender);if(key==='interests')return draft.interests.length>0;return Boolean(draft.readingPreferences[key]);}
function onboardingView(){const {step,draft,editing}=setupSession(),key=SETUP_STEPS[step].key;let answers='';
 if(key==='name')answers=`<label class="intro-name-label"><span class="sr-only">불릴 이름</span><input id="intro-name" aria-label="불릴 이름" maxlength="12" autocomplete="nickname" placeholder="별명도 좋아" value="${esc(draft.name)}"></label>`;
 else if(key==='age')answers=`<p class="intro-hint">부모님과 세는 나이로 골라 주세요.</p><div class="age-choices">${[5,6,7,8,9,10,11,12,13].map(n=>`<button class="intro-option age-option ${draft.age===n?'selected':''}" data-intro-age="${n}" aria-pressed="${draft.age===n}"><strong>${n}</strong><span>살</span></button>`).join('')}</div>`;
 else if(key==='gender')answers=`<div class="gender-choices">${[['girl','🙋‍♀️','여자아이'],['boy','🙋‍♂️','남자아이']].map(([v,img,t])=>`<button class="intro-option gender-option ${draft.gender===v?'selected':''}" data-intro-gender="${v}" aria-pressed="${draft.gender===v}"><span class="option-symbol" aria-hidden="true">${img}</span><span>${t}</span></button>`).join('')}</div><button class="intro-skip ${draft.gender==='skip'?'selected':''}" data-intro-gender="skip" aria-pressed="${draft.gender==='skip'}">건너뛰기</button>`;
 else if(key==='interests')answers=`<p class="intro-hint">좋아하는 걸 3개까지 골라 줘.</p><div class="interest-choices">${PROFILE.interests.map(t=>`<button class="intro-option interest-option ${draft.interests.includes(t.id)?'selected':''}" data-intro-interest="${t.id}" aria-pressed="${draft.interests.includes(t.id)}"><span class="option-symbol" aria-hidden="true">${t.emoji}</span><span>${t.label}</span>${draft.interests.includes(t.id)?`<i class="choice-check">${icon('check')}</i>`:''}</button>`).join('')}</div><button class="intro-skip" data-action="intro-skip-interests">아직 모르겠어</button>`;
 else if(key==='storyLevel')answers=`<p class="intro-level-note">${draft.age}살, 너의 속도에 맞춰 볼게.</p><div class="series-first-level"><b>${window.SiaLearning.core.initial(draft,'story','ko')}</b><span>${window.SiaLearning.core.BAND_LABEL[window.SiaLearning.core.ageBand(draft.age)]} 이야기 · 레벨 1 (1화부터)</span></div><p class="series-small">다 하고 나서 어땠는지 알려 줘.<br>다음에는 너에게 더 잘 맞춰 줄게.</p>`;
 else answers=`<div class="reading-choices">${PROFILE.choices[key].map(c=>`<button class="intro-option reading-choice ${draft.readingPreferences[key]===c.id?'selected':''}" data-intro-reading="${c.id}" aria-pressed="${draft.readingPreferences[key]===c.id}">${icon(c.icon)}<span><b>${c.label}</b><small>${c.sample}</small></span>${draft.readingPreferences[key]===c.id?icon('check'):''}</button>`).join('')}</div>`;
 return `<section class="intro-screen" aria-labelledby="intro-question"><div class="intro-progress" aria-label="자기소개 ${step+1} / ${SETUP_STEPS.length}">${SETUP_STEPS.map((x,n)=>`<i class="${n<=step?'done':''}"></i>`).join('')}</div><div class="intro-haru"><img src="assets/${step===0?'happy':step===3?'curious':'listening'}.png" alt="하루"></div><div class="intro-question-row"><h1 id="intro-question" tabindex="-1">${SETUP_STEPS[step].question}</h1><button class="icon-button" data-action="intro-speak" aria-label="질문 듣기">${icon('volume')}</button></div><div class="intro-answers">${answers}</div><div class="intro-bottom">${step>0?`<button class="btn outline" data-action="intro-back">${icon('back')}이전</button>`:`<span></span>`}<button class="btn primary" id="intro-next" data-action="intro-next" ${stepReady()?'':'disabled'}>${step===SETUP_STEPS.length-1?'하루와 시작':'다음'}${icon('arrow')}</button></div>${editing?'<button class="intro-skip intro-cancel" data-action="intro-cancel">바꾸지 않고 돌아가기</button>':''}</section>`;
}
function renderIntro(){shell();document.querySelector('#main').innerHTML=onboardingView();document.title='MY SIA · 하루와 첫 만남';}
function updateIntro(){persistDraft();renderIntro();}
function startIntroEdit(){onboarding={step:0,draft:newDraft(),editing:profileReady()};persistDraft();if(location.hash!=='#intro')location.hash='intro';else render();}
function introNext(skip=false){const session=setupSession();if(!skip&&!stepReady())return;if(session.step<SETUP_STEPS.length-1){session.step++;updateIntro();document.querySelector('#intro-question')?.focus();return;}let next;try{next=PROFILE.fromAnswers(state,session.draft);}catch{toast('빠진 답이 있어. 앞의 질문을 확인해 줘.');return;}const previous=state;state=next;if(!saveState()){state=previous;return;}onboarding=null;try{localStorage.removeItem('my-sia-intro-draft');}catch{}previewLevel=null;history.replaceState(null,'',window.SiaGameBridge.meta(new URLSearchParams(location.search).get('adventure'))?.astra?'#play':'#stories');render();if(previous.age&&window.SiaLearning.core.ageBand(previous.age)!==window.SiaLearning.core.ageBand(state.age))toast('나이가 바뀌어 묶음을 나이에 맞췄어요 ('+window.SiaLearning.core.BAND_LABEL[window.SiaLearning.core.ageBand(state.age)]+')');}
function speak(text,lang='ko-KR'){window.SiaVoice.speak(text,lang,()=>toast('읽어 주는 음성을 사용할 수 없어요.'));}
function greeting(){const n=state.name||'친구',last=n.charCodeAt(n.length-1);return n+(last>=0xac00&&last<=0xd7a3&&(last-0xac00)%28!==0?'아':'야');}
function interestLabels(){return (state.interests||[]).map(id=>PROFILE.interests.find(t=>t.id===id)?.label).filter(Boolean);}
function recommendationReason(item){const match=(state.interests||[]).find(id=>PROFILE.matches(item,id)),label=PROFILE.interests.find(t=>t.id===match)?.label;if(label)return `${label} 좋아하는 널 위해 골랐어.`;if(state.readingPreferences?.[state.lang]==='together')return '하루랑 한 장씩 같이 읽어 보자.';return '오늘은 이 학습지로 시작해 보자.';}

function saveState(){try{localStorage.setItem('my-sia-v1',JSON.stringify(state));return true;}catch{toast('저장 공간이 부족해요. 기록을 내보내 주세요.');return false;}}
const currentLevel=()=>LEVELS[PROFILE.ageStage(state.age)];
const levelNumber=()=>PROFILE.ageStage(state.age);
const completedToday=()=>Object.values(state.completed).filter(x=>x.date===today()).length;
const getItem=id=>LIBRARY.find(i=>i.id===id);
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
function shell(){
 document.querySelector('#sidebar').hidden=true;
 document.querySelector('#sidebar').innerHTML='';
 document.querySelector('#topbar').innerHTML=`<div class="simple-topbar"><div class="simple-brand-group">${route!=='home'?`<a href="#home" class="home-back" aria-label="처음으로">${icon('back')}</a>`:''}<a href="#home" class="simple-brand">MY SIA<span class="brand-star" aria-hidden="true">✳</span></a></div><div class="simple-top-actions">${route==='library'?`<button class="icon-button" data-action="toggle-search" aria-label="책 찾기">${icon('search')}</button>`:''}<button class="parent-button" data-action="profile" aria-label="부모님 공간">${icon('lock')}<span>부모님</span></button></div></div>`;
}
function recommended(){return PROFILE.ranked(LIBRARY,state,state.checkins[today()]||{}).slice(0,2).map(x=>x.item);}
function storyCard(i){return `<button class="story-card simple-book" data-open="${i.id}" aria-label="${esc(i.title)} 읽기"><div class="story-art"><img src="${i.cover||'assets/curious.png'}" alt="" loading="lazy">${state.completed[i.id]?`<span class="book-read" aria-label="읽은 책">${icon('check')}</span>`:''}</div><div class="story-body"><h3>${esc(personal(i.title))}</h3><span class="learning-book-level">레벨 ${i.level}</span></div></button>`;}
function home(){return `<section class="simple-home"><h1>${esc(greeting())}, 안녕!</h1><button class="intro-profile-chip" data-action="edit-intro" aria-label="내 소개 바꾸기">${state.age}살${state.gender==='girl'?' · 여아':state.gender==='boy'?' · 남아':''}${interestLabels().length?' · '+esc(interestLabels().join(' · ')):''}</button><div class="haru-stage"><div class="haru-speech">${state.readingPreferences?.[state.lang]==='together'?'하루랑 같이 읽자!':'오늘은 뭐 할까?'}</div><div class="haru-halo"></div><img class="haru-main" src="assets/${currentLevel().file}" alt="하루"><span class="haru-name">하루</span></div><div class="big-choices has-play"><a class="big-choice start-choice" href="#stories"><span class="choice-icon">${icon('book')}</span><span>이야기</span></a><a class="big-choice play-choice" href="#play"><span class="choice-icon">${icon('spark')}</span><span>놀이</span></a>${hasLibrary()?`<a class="big-choice book-choice" href="#library"><span class="choice-icon">${icon('book')}</span><span>책장</span></a>`:''}<button class="big-choice draw-choice" data-action="free-draw"><span class="choice-icon">${icon('pencil')}</span><span>그리기</span></button></div>${!hasLibrary()?'<p class="series-small">더 긴 이야기는 ‘이야기’에서 만나자</p>':''}<div class="learning-context">${window.SiaLearning.bandChip('story')}</div><a class="my-drawings-link" href="#notebook">내 그림 ${icon('chevron')}</a></section>`;}
function render(){route=location.hash.slice(1)||'home';if(!['home','library','notebook','companion','parents','intro','stories','story-parents','play'].includes(route))route='home';if(['parents','story-parents'].includes(route)||(route==='intro'&&profileReady())){if(!isParent()){parentGate();return;}}if(route==='library'&&!hasLibrary()){route='stories';history.replaceState(null,'','#stories');}if(route==='intro'||(!profileReady()&&!['parents','story-parents'].includes(route))){renderIntro();return;}shell();document.querySelector('#main').innerHTML=route==='home'?home():views[route]?views[route]():home();document.title=`MY SIA · ${{home:'오늘의 배움',library:'나의 서재',notebook:'그림 노트',play:'하루 놀이섬',companion:'나의 하루',parents:'부모님 공간',stories:'하루 이야기','story-parents':'이야기 답변지'}[route]}`;}
document.addEventListener('click',e=>{const lang=e.target.closest('[data-lang]');if(lang){state.lang=lang.dataset.lang;previewLevel=null;libraryPage=0;saveState();render();}const topic=e.target.closest('[data-topic]');if(topic){filter.topic=topic.dataset.topic;filter.query='';location.hash='library';if(route==='library')render();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});
let records={}, database=null, readerState=null, drawing=null, libraryLimit=6, libraryPage=0, previewLevel=null, searchOpen=false;
const dbReady=new Promise(resolve=>{
 try{const request=indexedDB.open('my-sia-work',1);request.onupgradeneeded=()=>request.result.createObjectStore('work',{keyPath:'id'});request.onerror=()=>resolve(false);request.onsuccess=()=>{database=request.result;const tx=database.transaction('work','readonly');const get=tx.objectStore('work').getAll();get.onsuccess=()=>{records=Object.fromEntries(get.result.map(r=>[r.id,r]));resolve(true);};get.onerror=()=>resolve(false);};}catch{resolve(false);}
});
function persistRecord(record){records[record.id]=record;record.updatedAt=new Date().toISOString();return new Promise(resolve=>{if(!database){setSaveStatus(false);resolve(false);return;}try{const tx=database.transaction('work','readwrite');tx.objectStore('work').put(structuredClone(record));tx.oncomplete=()=>{setSaveStatus(true);resolve(true);};tx.onerror=()=>{setSaveStatus(false);toast('기록을 저장하지 못했어요. 공간을 확인해 주세요.');resolve(false);};}catch{setSaveStatus(false);resolve(false);}});}
function setSaveStatus(saved){const node=document.querySelector('#save-status');if(node){node.textContent=saved?'저장됨':'저장되지 않음';node.dataset.saved=String(saved);}}
function personal(s){return String(s||'').replace(/시아/g,state.name);}
function svgImage(svg,cls=''){return `<img class="${cls}" src="data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg).replace(/'/g,'%27')}" alt="이야기 그림">`;}
function heading(title,subtitle,extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
function filteredLibrary(){return window.SiaLearning.core.libraryItems(LIBRARY,state).filter(i=>(filter.lang==='all'||i.lang===filter.lang)&&(filter.kind==='all'||i.kind===filter.kind)&&(!filter.query||`${i.title} ${i.summary} ${i.tags.join(' ')}`.toLowerCase().includes(filter.query.toLowerCase()))&&(!filter.topic||i.tags.some(t=>t.includes(filter.topic))));}
function libraryView(){return `<div class="simple-page-heading"><h1>책장</h1><div class="shelf-language"><button data-lang="ko" class="${state.lang==='ko'?'selected':''}" aria-pressed="${state.lang==='ko'}">한글</button><button data-lang="en" class="${state.lang==='en'?'selected':''}" aria-pressed="${state.lang==='en'}">English</button></div></div>${libraryContext()}${searchOpen?`<label class="search-field shelf-search">${icon('search')}<input id="library-search" type="search" placeholder="책 이름" value="${esc(filter.query)}" aria-label="책 이름 검색"></label>`:''}<div id="library-results"></div>`;}
function libraryContext(){const n=window.SiaLearning.level('library'),pending=Object.values(records).find(r=>r.learningAttempt?.completedAt&&!r.learningAttempt.feedback&&r.learningAttempt.lang===state.lang);return `<div class="learning-context">${window.SiaLearning.bandChip('library')}<span>${state.lang==='en'?'영어':'한글'} · <b>레벨 ${n}</b></span></div>${pending?`<button class="btn outline" data-library-reflect="${esc(pending.id)}">지난 활동은 어땠어?</button>`:''}`;}
function libraryResults(){filter.lang=state.lang;const list=filteredLibrary(),node=document.querySelector('#library-results');if(!node)return;const pages=Math.ceil(list.length/6);libraryPage=Math.min(libraryPage,Math.max(0,pages-1));node.innerHTML=list.length?`<div class="library-grid simple-shelf">${list.slice(libraryPage*6,libraryPage*6+6).map(storyCard).join('')}</div><div class="shelf-pagination"><button class="btn outline" data-action="previous-books" ${libraryPage===0?'disabled':''}>${icon('back')}이전</button><button class="btn primary" data-action="next-books" ${libraryPage>=pages-1?'disabled':''}>다른 책 ${icon('arrow')}</button></div>`:`<div class="empty-state"><img src="assets/no-results.png" alt=""><h2>다른 이름으로 찾아볼까?</h2><button class="btn secondary" data-action="reset-filters">책장 보기</button></div>`;}

function notebookView(){const drawings=Object.values(records).flatMap(r=>Object.entries(r.drawings||{}).filter(([,d])=>d.length).map(([key,strokes])=>({r,key,strokes}))).sort((a,b)=>b.r.updatedAt.localeCompare(a.r.updatedAt));return `${heading('내 그림','',`<button class="btn primary" data-action="free-draw">${icon('pencil')}새 그림</button>`)}${drawings.length?`<div class="notebook-grid">${drawings.map(({r,key,strokes},n)=>`<button class="note-card" data-note="${esc(r.id)}" data-area="${esc(key)}"><canvas class="note-preview" width="500" height="300" data-preview="${n}" aria-label="${esc(r.title)} 그림"></canvas><div><h3>${esc(r.title)}</h3><p>${new Date(r.updatedAt).toLocaleDateString('ko-KR')} · ${key.startsWith('q')?'생각 쓰기':'그림 그리기'}</p></div></button>`).join('')}</div>`:'<section class="empty-notebook"><div class="empty-state"><img src="assets/profile-photo.png" alt="그림을 들고 있는 하루"><h2>아직 그림이 없네!</h2><button class="btn primary" data-action="free-draw">그리기</button></div></section>'}`;}
function paintNotebook(){const all=Object.values(records).flatMap(r=>Object.entries(r.drawings||{}).filter(([,d])=>d.length).map(([key,strokes])=>({r,key,strokes}))).sort((a,b)=>b.r.updatedAt.localeCompare(a.r.updatedAt));document.querySelectorAll('[data-preview]').forEach(async c=>{const value=all[Number(c.dataset.preview)],item=getItem(value.r.id),pages=item?readingPages(item,value.r.flowVersion===2):[],page=pageForArea(pages,value.key),background=value.key.startsWith('draw')&&item?pages[page]?.background:null;if(!background){drawStrokes(c,value.strokes);return;}const ink=document.createElement('canvas');ink.width=c.width;ink.height=c.height;drawStrokes(ink,value.strokes);const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(background);try{await img.decode();const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);ctx.drawImage(ink,0,0);}catch{drawStrokes(c,value.strokes);}});}
function companionView(){const n=previewLevel??levelNumber(),l=LEVELS[n];return `${heading('하루의 모습','학습 레벨에 따라 하루의 모습이 달라집니다.')}<section class="simple-companion"><img src="assets/${l.file}" alt="레벨 ${n} 하루"><h2>L${n} · ${l.name}</h2></section><div class="level-journey">${LEVELS.map((x,k)=>`<button class="level-stop ${n===k?'selected':''}" data-preview-level="${k}" aria-pressed="${n===k}"><img src="assets/${x.file}" alt=""><b>L${k}</b></button>`).join('')}</div><div class="center"><a href="#parents" class="btn outline">부모님 공간으로</a></div>`;}
function parentsView(){const complete=Object.entries(state.completed).sort((a,b)=>b[1].at.localeCompare(a[1].at));return `${heading('부모님 공간','아이에게 맞는 속도와 이야기를 함께 찾아 주세요.')}${window.SiaVoiceSettings.view()}<a class="series-parent-link" href="#story-parents"><img src="assets/listening.png" alt=""><div><strong>이야기 답변지 · 읽기 기록</strong><p>아이의 답과 모범답안을 함께 확인해요.</p></div>${icon('chevron')}</a>${window.SiaLearning.parentSummary()}${window.SiaPlay.parentSummary()}<div class="parent-grid"><section class="settings-card"><h2>배움 프로필</h2><div class="profile-summary"><div><dt>소개</dt><dd>${state.age?state.age+'살 · ':''}${state.gender==='girl'?'여아':state.gender==='boy'?'남아':state.gender==='skip'?'성별 건너뜀':'첫 질문이 필요해요'}</dd></div><div><dt>관심사</dt><dd>${esc(interestLabels().join(' · ')||'아직 고르지 않았어요')}</dd></div><button class="text-button" data-action="edit-intro">하루에게 다시 소개하기 ${icon('chevron')}</button></div><form id="profile-form"><label>아이가 불릴 이름<input name="name" value="${esc(state.name)}" maxlength="12" required autocomplete="off"></label><div class="form-row"><label>나이 (세는 나이)<select name="age" required><option value="" ${!state.age?'selected':''} disabled>골라 주세요</option>${[5,6,7,8,9,10,11,12,13].map(n=>`<option value="${n}" ${state.age===n?'selected':''}>${n}살</option>`).join('')}</select></label><label>성별<select name="gender">${[['skip','건너뛰기'],['girl','여아'],['boy','남아']].map(([v,t])=>`<option value="${v}" ${(state.gender||'skip')===v?'selected':''}>${t}</option>`).join('')}</select></label></div><fieldset class="profile-form-interests"><legend>관심사 · 3개까지</legend>${PROFILE.interests.map(t=>`<label><input type="checkbox" name="interests" value="${t.id}" ${(state.interests||[]).includes(t.id)?'checked':''}>${t.label}</label>`).join('')}</fieldset><p class="profile-gender-note">성별은 자기소개에만 사용합니다. 소재와 난이도는 관심사·나이·읽기 수준으로 고릅니다.</p><div class="form-row"><label>한글 읽기 경험<select name="readingKo">${PROFILE.choices.ko.map(c=>`<option value="${c.id}" ${state.readingPreferences?.ko===c.id?'selected':''}>${c.label}</option>`).join('')}</select></label><label>영어 읽기 경험<select name="readingEn">${PROFILE.choices.en.map(c=>`<option value="${c.id}" ${state.readingPreferences?.en===c.id?'selected':''}>${c.label}</option>`).join('')}</select></label></div><label>하루에 만날 이야기<select name="daily">${[1,2,3].map(n=>`<option value="${n}" ${state.daily===n?'selected':''}>${n}개</option>`).join('')}</select></label><p class="field-help">모든 활동은 나이 묶음 안에서 시작합니다. 책장은 5–7살 전용이며, 8살부터는 나이에 맞는 연속 이야기를 읽어요. ‘어땠어?’와 실제 결과를 반영해 한 단계씩 조절하고, 묶음은 부모님만 바꿀 수 있어요.</p><button class="btn primary" type="submit">설정 저장 ${icon('check')}</button><p class="settings-feedback" role="status"></p></form><a class="text-button" href="#companion">하루 모습 보기 ${icon('chevron')}</a></section><section class="settings-card"><h2>차곡차곡 쌓인 발견</h2><div class="stat-row"><div><b>${complete.length}</b><span>읽은 이야기</span></div><div><b>${Object.values(records).filter(r=>Object.values(r.drawings||{}).some(d=>d.length)).length}</b><span>그림을 남긴 활동</span></div><div><b>${Object.keys(state.checkins).length}</b><span>마음을 나눈 날</span></div></div><h3 class="recent-title">최근 만난 이야기</h3>${complete.length?complete.slice(0,5).map(([id,c])=>`<button class="history-row" data-open="${id}"><span>${esc(getItem(id)?.title||id)}</span><small>${c.date}</small>${icon('chevron')}</button>`).join(''):'<p class="muted small">첫 이야기를 마치면 여기에 기록됩니다.</p>'}<div class="local-note">${icon('lock')}<p>아이 소개, 필기와 학습 기록은 이 브라우저에 저장됩니다. 다른 기기와 자동으로 동기화되지 않습니다.</p></div><button class="btn outline" data-action="backup">${icon('download')}학습 기록 내보내기</button></section></div>`;}
const views={play:()=>window.SiaPlay.view(),library:libraryView,notebook:notebookView,companion:companionView,parents:parentsView,stories:()=>window.SiaStoryMode.view(),'story-parents':()=>window.SiaStoryMode.parentsView()};
const originalRender=render;
render=function(){originalRender();if(route==='library')libraryResults();if(route==='notebook')paintNotebook();window.SiaStoryMode.mount(route);window.SiaPlay.mount(route);};
function showModal(content){const modal=document.querySelector('#modal');modal.innerHTML=content;if(!modal.open)modal.showModal();}
function modalHeader(title){return `<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="닫기">${icon('close')}</button></div>`;}
let checkinDraft={step:0,energy:'',topic:''};
function startCheckin(force=false){if(!profileReady()){startIntroEdit();return;}if(state.checkins[today()]&&!force){checkinResults();return;}checkinDraft={step:0,energy:'',topic:''};checkinStep();}
function checkinStep(){showModal(`<div class="modal-body simple-checkin">${modalHeader('지금 기분은?')}<div class="mood-choices">${[['good','happy.png','좋아'],['calm','calm.png','보통'],['tired','sleepy.png','쉬고 싶어']].map(([v,img,t])=>`<button class="mood-choice" data-checkin="${v}"><img src="assets/${img}" alt=""><span>${t}</span></button>`).join('')}</div><button class="text-button" data-action="skip-checkin">모르겠어</button></div>`);}
function nextCheckin(){state.checkins[today()]={energy:checkinDraft.energy,topic:''};saveState();render();checkinResults();}
function checkinResults(){const picks=recommended();if(!picks.length){document.querySelector('#modal').close();location.hash='stories';return;}showModal(`<div class="modal-body simple-recommendations">${modalHeader('같이 해 볼까?')}<p class="recommendation-reason">${esc(recommendationReason(picks[0]))}</p><div class="story-grid">${picks.map(storyCard).join('')}</div><div class="center"><button class="btn outline" data-action="browse-all">다른 학습지 ${icon('arrow')}</button></div></div>`);}
function readingPages(item,guided=false){
 if(item.sheet){const s=item.sheet;if(guided)return [...s.body.map((text,n)=>({kind:'read',guided:true,text:[text],svg:s.svg,words:n===s.body.length-1?s.words:[]})),...s.questions.map((question,n)=>({kind:'question',guided:true,qs:[question],answerKeys:[`0-${n}`],canvasKey:`q-${n}`,context:s.body,contextSvg:s.svg})),{kind:'draw',guided:true,prompt:s.draw,background:s.svg,canvasKey:'draw-1'}];return [{...s,text:s.body,qs:s.questions,kind:'read'},{kind:'draw',prompt:s.draw,background:s.svg}];}
 const data=item.story||item.school;const pages=data.pages.map(p=>({...p,kind:'read',qs:p.q?[p.q]:[]}));if(data.color_me)pages.push({kind:'draw',prompt:data.color_me_lead||'마음에 드는 색으로 칠해 봐.',background:data.color_me});pages.push({kind:'draw',prompt:data.draw||data.free_draw||'이야기를 읽고 떠오른 장면을 그려 봐.'});return pages;
}
function pageForArea(pages,area){const explicit=pages.findIndex(p=>p.canvasKey===area);if(explicit>=0)return explicit;const match=area?.match(/-(\d+)$/);return match?Math.min(Number(match[1]),pages.length-1):0;}
async function openReader(id,area){
 if(!profileReady()){startIntroEdit();return false;}await dbReady;const item=getItem(id);let record=records[id];if(!item&&!record)return false;if(item&&!area&&!isParent()&&!window.SiaLearning.core.libraryItems(LIBRARY,state).some(i=>i.id===id)){toast('지금 나이 묶음의 이야기를 골라 주세요.');return false;}
 const pages=item?readingPages(item,!record||record.flowVersion===2):[{kind:'draw',prompt:record.prompt||'마음껏 그려 봐!'}];
 if(!record)record={id,title:item.title,drawings:{},answers:{},page:0,flowVersion:2,updatedAt:new Date().toISOString()};
 if(item&&!area){if(record.learningAttempt?.completedAt&&!record.learningAttempt.feedback){showLibraryFeedback(record);return true;}if(!record.learningAttempt||record.learningAttempt.completedAt){record.learningAttempt=window.SiaLearning.start('library','library-'+(crypto.randomUUID?.()||Date.now()),{lang:item.lang,title:item.title});record.page=0;}}
 readerState={item,record,pages,index:Math.max(0,Math.min(record.page||0,pages.length-1)),returnFocus:document.activeElement};if(area)readerState.index=pageForArea(pages,area);if(item){state.lastItem=id;saveState();}
 const modal=document.querySelector('#modal');if(modal.open)modal.close();document.querySelector('#reader').hidden=false;document.querySelector('.workspace').inert=true;document.querySelector('#sidebar').inert=true;document.body.style.overflow='hidden';renderReader();document.querySelector('#reader-close').focus();return true;
}
function readerGuide(p){if(!p.guided)return '';const text=p.kind==='question'?'네 생각을 쓰거나 그려 줘.':p.kind==='draw'?'이제 네 그림으로 들려줘!':state.readingPreferences?.[readerState.item.lang]==='together'?'소리로 듣고 같이 읽어 보자.':'한 장씩 같이 읽어 보자.';return `<div class="haru-guide"><img src="assets/${p.kind==='question'?'curious.png':'listening.png'}" alt="하루"><p>${text}</p></div>`;}
function renderReader(){
 if(!readerState)return;if(drawing){drawing.observer.disconnect();drawing=null;}
 const {item,record,pages,index}=readerState,p=pages[index],isDraw=p.kind==='draw',isQuestion=p.kind==='question',q=p.qs||[],title=personal(item?.title||record.title),key=p.canvasKey||`${isDraw?'draw':'q'}-${index}`;
 let content='';
 if(isDraw)content=`<div class="drawing-prompt"><h3>${esc(personal(p.prompt))}</h3></div>${canvasMarkup(key,p.background)}`;
 else if(isQuestion){const answerKey=p.answerKeys[0];content=`<section class="guided-question"><div class="answer-panel"><h3>${esc(personal(q[0]))}</h3>${canvasMarkup(key)}<details class="typed-answer"><summary>글자로 쓰기</summary><label><span class="sr-only">내 답</span><textarea data-answer="${answerKey}" aria-label="내 답" placeholder="여기에 써 봐" rows="3">${esc(record.answers[answerKey]||'')}</textarea></label></details></div><details class="question-context"><summary>이야기·그림 다시 보기</summary>${p.contextSvg?`<div class="page-illustration">${svgImage(p.contextSvg)}</div>`:''}${p.context.map(t=>`<p>${esc(personal(t))}</p>`).join('')}</details></section>`;}
 else content=`<div class="reading-layout ${p.guided?'guided-read':''}"><article class="book-page">${p.svg?`<div class="page-illustration">${svgImage(p.svg)}</div>`:''}${p.part&&item.school?.part_titles?`<span class="chapter-label">${p.part}부 · ${esc(item.school.part_titles[p.part-1])}</span>`:''}<div class="reading-text" lang="${item.lang}">${(p.text||[]).map(t=>`<p>${esc(personal(t))}</p>`).join('')}</div>${p.words?.length?`<div class="word-list">${p.words.map(w=>`<details><summary>${esc(w.term)}</summary><p>${esc(w.meaning)}</p></details>`).join('')}</div>`:''}</article>${p.guided?'':`<aside class="answer-panel">${q.length?`${q.map((question,n)=>`<label class="question-label">${q.length>1?`<span class="question-number">${n+1}</span>`:''}${esc(personal(question))}<textarea data-answer="${index}-${n}" placeholder="여기에 써 봐" rows="3">${esc(record.answers[`${index}-${n}`]||'')}</textarea></label>`).join('')}${canvasMarkup(key)}${p.answer?`<details class="answer-key"><summary>부모님 답안 가이드</summary><p>${esc(p.answer)}</p>${p.check?`<p>${esc(p.check)}</p>`:''}</details>`:''}`:`<div class="reading-friend"><img src="assets/listening.png" alt="이야기를 듣는 하루"></div>`}</aside>`}</div>`;
 document.querySelector('#reader').innerHTML=`<section role="dialog" aria-modal="true" aria-labelledby="reader-title" class="reader-shell"><header class="reader-header"><button id="reader-close" aria-label="나가기" class="btn reader-back" data-action="close-reader">${icon('back')}<span>나가기</span></button><div class="reader-title-wrap"><h2 id="reader-title">${esc(title)}</h2><span id="save-status" role="status">저장 중</span></div><button class="icon-button" data-action="read-aloud" aria-label="${isDraw?'그리기 안내':isQuestion?'질문':'이야기'} 소리로 듣기">${icon('volume')}</button></header><div class="reader-progress"><i style="width:${(index+1)/pages.length*100}%"></i></div><div class="reader-content ${isDraw?'drawing-page':''}">${readerGuide(p)}${content}</div><footer class="reader-footer"><button class="btn outline" data-action="prev-page" ${index===0?'disabled':''}>${icon('back')}이전</button><span>${index+1} <span class="muted">/ ${pages.length}</span></span><button class="btn primary" data-action="${index===pages.length-1?'finish-reading':'next-page'}">${index===pages.length-1?'다 했어!':'다음'}${icon(index===pages.length-1?'check':'arrow')}</button></footer></section>`;
 record.page=index;persistRecord(record);if(isDraw||q.length)setupCanvas(key,p.background);document.querySelector('.reader-content').scrollTop=0;
}

function canvasMarkup(key,background){return `<div class="drawing-tools simple-drawing-tools" aria-label="그리기 도구"><div class="color-tools">${[['#243f35','먹색'],['#3561e9','파랑'],['#e56860','빨강'],['#e9b941','노랑'],['#409371','초록']].map(([c,n],i)=>`<button class="color-dot ${i===0?'selected':''}" style="--color:${c}" data-color="${c}" aria-label="${n} 펜" aria-pressed="${i===0}"></button>`).join('')}</div><div class="pen-tools"><button class="tool-button" data-action="eraser" aria-label="지우개" aria-pressed="false">${icon('erase')}</button><button class="tool-button" data-action="undo-drawing" aria-label="되돌리기">${icon('undo')}</button></div></div><div class="drawing-paper ${background?'coloring':''}">${background?`<div class="paper-underlay">${svgImage(background)}</div>`:''}<canvas id="drawing-canvas" width="1000" height="600" aria-label="그리는 칸" role="img"></canvas></div><input id="touch-enabled" type="checkbox" checked hidden><select id="pen-width" hidden aria-label="펜 굵기"><option value="7">보통</option></select>`;}

function drawStrokes(canvas,strokes){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);for(const s of strokes){if(!s.p?.length)continue;ctx.save();ctx.globalCompositeOperation=s.erase?'destination-out':'source-over';ctx.strokeStyle=s.c;ctx.fillStyle=s.c;ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=s.w*canvas.width/1000;ctx.beginPath();ctx.moveTo(s.p[0][0]*canvas.width,s.p[0][1]*canvas.height);if(s.p.length===1){ctx.lineTo(s.p[0][0]*canvas.width+.01,s.p[0][1]*canvas.height+.01);}for(let j=1;j<s.p.length;j++)ctx.lineTo(s.p[j][0]*canvas.width,s.p[j][1]*canvas.height);ctx.stroke();ctx.restore();}}
function setupCanvas(key,background){const canvas=document.querySelector('#drawing-canvas');if(!canvas)return;const record=readerState.record;record.drawings[key]??=[];drawing={canvas,key,background,color:'#243f35',width:7,erase:false,active:null,pointer:null};const resize=()=>{if(!drawing||drawing.canvas!==canvas)return;const rect=canvas.getBoundingClientRect();canvas.width=Math.max(1,Math.round(rect.width*Math.min(devicePixelRatio||1,2)));canvas.height=Math.round(canvas.width*.6);drawStrokes(canvas,record.drawings[key]);};drawing.observer=new ResizeObserver(resize);drawing.observer.observe(canvas);resize();const point=e=>{const b=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))];};canvas.addEventListener('pointerdown',e=>{if(!drawing||drawing.active||e.button!==0||e.isPrimary===false)return;if(e.pointerType==='touch'&&!document.querySelector('#touch-enabled').checked)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);drawing.pointer=e.pointerId;drawing.active={c:drawing.color,w:drawing.erase?36:drawing.width,erase:drawing.erase,p:[point(e)]};record.drawings[key].push(drawing.active);drawStrokes(canvas,record.drawings[key]);});canvas.addEventListener('pointermove',e=>{if(!drawing?.active||drawing.pointer!==e.pointerId)return;e.preventDefault();for(const event of (e.getCoalescedEvents?.()||[e]))drawing.active.p.push(point(event));drawStrokes(canvas,record.drawings[key]);});const stop=e=>{if(!drawing?.active||drawing.pointer!==e.pointerId)return;drawing.active=null;drawing.pointer=null;persistRecord(record);};canvas.addEventListener('pointerup',stop);canvas.addEventListener('pointercancel',stop);canvas.addEventListener('lostpointercapture',stop);}
async function closeReader(){if(!readerState)return;await persistRecord(readerState.record);window.SiaVoice?.stop();drawing?.observer.disconnect();drawing=null;const previous=readerState.returnFocus;readerState=null;document.querySelector('#reader').hidden=true;document.querySelector('#reader').innerHTML='';document.querySelector('.workspace').inert=false;document.querySelector('#sidebar').inert=false;document.body.style.overflow='';render();if(previous?.isConnected)previous.focus();else document.querySelector('#main').focus();}
async function changePage(delta){if(!readerState)return;await persistRecord(readerState.record);window.SiaVoice?.stop();readerState.index=Math.max(0,Math.min(readerState.pages.length-1,readerState.index+delta));renderReader();}
async function finishReading(){if(!readerState)return;const item=readerState.item,finishedRecord=readerState.record;if(finishedRecord.learningAttempt)finishedRecord.learningAttempt.completedAt??=new Date().toISOString();const saved=await persistRecord(readerState.record);if(!saved){toast('기록을 저장하지 못했어요. 그림 저장 버튼으로 보관해 주세요.');return;}if(item&&!state.completed[item.id]){state.completed[item.id]={date:today(),at:new Date().toISOString()};saveState();}await closeReader();if(finishedRecord.learningAttempt){showLibraryFeedback(finishedRecord);return;}showModal(`<div class="modal-body celebration">${modalHeader('잘했어!')}<img src="assets/congratulations.png" alt="축하하는 하루"><h3>오늘도 즐거웠어!</h3><button class="btn primary" data-action="close-modal">좋아! ${icon('check')}</button><button class="text-button" data-action="view-notebook">내 그림 ${icon('arrow')}</button></div>`);}
let libraryFeedbackRecord=null;
function showLibraryFeedback(record){libraryFeedbackRecord=record;showModal(`<div class="modal-body celebration">${modalHeader('함께 해냈어!')}<img src="assets/congratulations.png" alt="축하하는 하루"><div id="library-learning-feedback">${window.SiaLearning.feedbackHtml(record.learningAttempt)}</div><button class="btn primary" data-action="close-modal" ${record.learningAttempt.feedback?'':'disabled'}>${record.learningAttempt.domain==='drawing'?'다 했어!':'책장으로'}</button></div>`);}
document.addEventListener('click',async event=>{const resume=event.target.closest('[data-library-reflect]');if(resume){const record=records[resume.dataset.libraryReflect];if(record)showLibraryFeedback(record);return;}const choice=event.target.closest('#library-learning-feedback [data-learning-feedback]');if(!choice||!libraryFeedbackRecord)return;const record=libraryFeedbackRecord;if(window.SiaLearning.respond(record.learningAttempt,choice.dataset.learningFeedback,{ready:false})){await persistRecord(record);showLibraryFeedback(record);libraryPage=0;if(route==='library')render();}});
async function freeDraw(){if(!profileReady()){startIntroEdit();return;}await dbReady;const id='drawing-'+Date.now();records[id]={id,title:`${state.name}의 자유 그림`,prompt:window.SiaLearning.core.drawingPrompt(state),learningAttempt:window.SiaLearning.start('drawing',id),drawings:{},answers:{},page:0,updatedAt:new Date().toISOString()};openReader(id);}
function readAloud(){if(!readerState)return;const p=readerState.pages[readerState.index];speak(personal(p.prompt||(p.kind==='question'?p.qs:p.text||[]).join(' ')),readerState.item?.lang==='en'?'en-US':'ko-KR');}
function downloadFile(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function downloadDrawing(){if(!drawing)return;const out=document.createElement('canvas');out.width=1400;out.height=840;const ctx=out.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,1400,840);if(drawing.background){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(drawing.background);try{await img.decode();ctx.drawImage(img,0,0,1400,840);}catch{}}ctx.drawImage(drawing.canvas,0,0,1400,840);out.toBlob(blob=>{if(blob)downloadFile(blob,`MY-SIA-${today()}.png`);},'image/png');}
document.addEventListener('click',async e=>{
 const storyLevel=e.target.closest('[data-intro-story-level]');if(storyLevel){setupSession().draft.storyLevel=Number(storyLevel.dataset.introStoryLevel);updateIntro();return;}
 const age=e.target.closest('[data-intro-age]');if(age){setupSession().draft.age=Number(age.dataset.introAge);updateIntro();return;}
 const gender=e.target.closest('[data-intro-gender]');if(gender){setupSession().draft.gender=gender.dataset.introGender;updateIntro();return;}
 const interest=e.target.closest('[data-intro-interest]');if(interest){const values=setupSession().draft.interests,id=interest.dataset.introInterest;if(values.includes(id))onboarding.draft.interests=values.filter(v=>v!==id);else if(values.length<3)values.push(id);else{toast('좋아하는 걸 3개까지만 골라 줘.');return;}updateIntro();document.querySelector(`[data-intro-interest="${id}"]`)?.focus();return;}
 const reading=e.target.closest('[data-intro-reading]');if(reading){const lang=SETUP_STEPS[setupSession().step].key;if(!['ko','en'].includes(lang))return;onboarding.draft.readingPreferences[lang]=reading.dataset.introReading;onboarding.draft.storyLevel=1;updateIntro();return;}

 const open=e.target.closest('[data-open]');if(open){await openReader(open.dataset.open);return;}
 const note=e.target.closest('[data-note]');if(note){await openReader(note.dataset.note,note.dataset.area);return;}
 const lang=e.target.closest('[data-filter-lang]');if(lang){filter.lang=lang.dataset.filterLang;libraryLimit=24;render();}
 const kind=e.target.closest('[data-filter-kind]');if(kind){filter.kind=kind.dataset.filterKind;libraryLimit=24;render();}
 const preview=e.target.closest('[data-preview-level]');if(preview){previewLevel=Number(preview.dataset.previewLevel);render();}
 const choice=e.target.closest('[data-checkin]');if(choice){checkinDraft.energy=choice.dataset.checkin;nextCheckin();}
 const color=e.target.closest('[data-color]');if(color&&drawing){drawing.color=color.dataset.color;drawing.erase=false;document.querySelectorAll('[data-color]').forEach(b=>{b.classList.toggle('selected',b===color);b.setAttribute('aria-pressed',b===color?'true':'false');});document.querySelector('[data-action="eraser"]').setAttribute('aria-pressed','false');}
 const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
 switch(action){
 case 'profile':location.hash='parents';break;
 case 'edit-intro':startIntroEdit();break;
 case 'intro-next':introNext();break;
 case 'intro-back':setupSession().step=Math.max(0,onboarding.step-1);updateIntro();document.querySelector('#intro-question')?.focus();break;
 case 'intro-skip-interests':setupSession().draft.interests=[];introNext(true);break;
 case 'intro-cancel':onboarding=null;try{localStorage.removeItem('my-sia-intro-draft');}catch{}location.hash='home';break;
 case 'intro-speak':{const step=SETUP_STEPS[setupSession().step],options=step.key==='gender'?' 여자아이, 남자아이. 건너뛰어도 돼.':step.key==='interests'?' 좋아하는 걸 세 개까지 골라 줘. '+PROFILE.interests.map(t=>t.label).join(', '):['ko','en'].includes(step.key)?' '+PROFILE.choices[step.key].map(t=>t.label).join(', '):'';speak(step.question+options);break;}

 case 'toggle-search':searchOpen=!searchOpen;render();document.querySelector('#library-search')?.focus();break;
 case 'next-books':libraryPage++;libraryResults();document.querySelector('#main').scrollIntoView({behavior:'smooth'});break;
 case 'previous-books':libraryPage=Math.max(0,libraryPage-1);libraryResults();document.querySelector('#main').scrollIntoView({behavior:'smooth'});break;
 case 'checkin':startCheckin();break;
 case 'close-modal':document.querySelector('#modal').close();break;
 case 'next-checkin':nextCheckin();break;
 case 'skip-checkin':checkinDraft[checkinDraft.step===0?'energy':'topic']='';nextCheckin();break;
 case 'redo-checkin':startCheckin(true);break;
 case 'browse-all':document.querySelector('#modal').close();location.hash='library';break;
 case 'view-notebook':document.querySelector('#modal').close();location.hash='notebook';break;
 case 'clear-topic':filter.topic='';render();break;
 case 'reset-filters':filter={lang:'all',kind:'all',topic:'',query:''};libraryLimit=24;render();break;
 case 'more-books':libraryLimit+=24;libraryResults();break;
 case 'free-draw':freeDraw();break;
 case 'close-reader':await closeReader();break;
 case 'next-page':await changePage(1);break;
 case 'prev-page':await changePage(-1);break;
 case 'finish-reading':await finishReading();break;
 case 'read-aloud':readAloud();break;
 case 'eraser':if(drawing){drawing.erase=!drawing.erase;e.target.closest('button').setAttribute('aria-pressed',String(drawing.erase));}break;
 case 'undo-drawing':if(drawing){readerState.record.drawings[drawing.key].pop();drawStrokes(drawing.canvas,readerState.record.drawings[drawing.key]);persistRecord(readerState.record);}break;
 case 'download-drawing':downloadDrawing();break;
 case 'backup':await dbReady;downloadFile(new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),profile:state,work:records,play:window.SiaPlay.exportData()},null,2)],{type:'application/json'}),`MY-SIA-records-${today()}.json`);break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='intro-name'){setupSession().draft.name=e.target.value;persistDraft();document.querySelector('#intro-next').disabled=!stepReady();}if(e.target.id==='library-search'){filter.query=e.target.value;libraryPage=0;libraryResults();}if(e.target.matches('[data-answer]')&&readerState){readerState.record.answers[e.target.dataset.answer]=e.target.value;persistRecord(readerState.record);}});
document.addEventListener('change',e=>{if(e.target.matches('#profile-form input[name=interests]')){const selected=document.querySelectorAll('#profile-form input[name=interests]:checked');if(selected.length>3){e.target.checked=false;toast('관심사는 3개까지 골라 주세요.');}}if(e.target.id==='pen-width'&&drawing)drawing.width=Number(e.target.value);});
document.addEventListener('submit',e=>{if(e.target.id!=='profile-form')return;e.preventDefault();if(!isParent())return;const data=new FormData(e.target),name=String(data.get('name')).trim(),age=Number(data.get('age')),interests=data.getAll('interests').map(String);const draft={name,age,gender:String(data.get('gender')),interests,readingPreferences:{ko:String(data.get('readingKo')),en:String(data.get('readingEn'))}};let updated;try{updated=PROFILE.fromAnswers(state,draft);}catch{toast('이름과 나이, 관심사를 확인해 주세요.');return;}updated.daily=Number(data.get('daily'));const old=state;state=updated;if(!saveState()){state=old;return;}onboarding=null;try{localStorage.removeItem('my-sia-intro-draft');}catch{}previewLevel=null;render();const node=document.querySelector('.settings-feedback');if(window.SiaLearning.core.ageBand(old.age)!==window.SiaLearning.core.ageBand(state.age))toast('나이가 바뀌어 묶음을 나이에 맞췄어요 ('+window.SiaLearning.core.BAND_LABEL[window.SiaLearning.core.ageBand(state.age)]+')');if(node)node.textContent=state.age>=8&&state.readingPreferences.en==='together'?'영어가 처음이라면 부모님 공간에서 영어 묶음을 낮출 수 있어요.':'저장했어요. 다음 활동에 반영됩니다.';});

document.addEventListener('keydown',e=>{if(e.target.id==='intro-name'&&e.key==='Enter'&&!e.isComposing){e.preventDefault();introNext();return;}if(!readerState)return;if(e.key==='Escape'){e.preventDefault();closeReader();}if(e.key==='Tab'){const focus=[...document.querySelector('#reader').querySelectorAll('button:not(:disabled),textarea,select,input,summary')];const first=focus[0],last=focus[focus.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('pagehide',()=>{if(readerState)persistRecord(readerState.record);});
window.SiaVoiceSettings.init({isParent});
window.SiaLearning.init({getProfile:()=>state,saveProfile:saveState,toast,isParent,render:()=>render()});
window.SiaPlay.init({getProfile:()=>state,toast,icon,speak});
window.SiaStoryMode.init({getProfile:()=>state,saveProfile:saveState,profileReady,isParent,requireProfile:startIntroEdit,toast,icon,speak,showModal,render:()=>render(),downloadFile});
render();dbReady.then(ok=>{if(!ok)toast('필기 저장을 사용할 수 없어요. 브라우저 설정을 확인해 주세요.');if(route==='notebook'||route==='parents')render();});
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tools=[{name:'search_sia_library',title:'MY SIA 서재 검색',description:'Search existing learning materials by title, summary, and language. Does not change progress.',inputSchema:{type:'object',properties:{query:{type:'string'},language:{enum:['all','ko','en']}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(typeof input?.query!=='string'||input.query.length>120||input.language&&!['all','ko','en'].includes(input.language))throw new Error('Invalid search');return window.SiaLearning.core.libraryItems(LIBRARY,{...state,lang:input.language==='en'?'en':state.lang}).filter(i=>(!input.language||input.language==='all'||i.lang===input.language)&&`${i.title} ${i.summary}`.toLowerCase().includes(input.query.toLowerCase())).slice(0,12).map(i=>({id:i.id,title:i.title,language:i.lang,level:i.band}));}},{name:'start_sia_reading',title:'MY SIA 이야기 열기',description:'Open an existing story at the saved page. This starts reading and saves last opened material; it does not mark it complete.',inputSchema:{type:'object',properties:{itemId:{type:'string'}},required:['itemId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(typeof input?.itemId!=='string'||!getItem(input.itemId))throw new Error('Unknown material');await openReader(input.itemId);return readerState?{opened:true,id:input.itemId,page:readerState.index+1}:{opened:false,needsProfile:true};}}];
 for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
